// One car of a match carpool. `editable` adds the delete button (Afwijking only); `highlightId`
// tints the row when that family drives it or has its daughter in it.
export function matchCarRowHtml(c, opts){
  opts = opts||{};
  const girlIds = c.girlIds||[];
  const driver = c.driverFamilyId? esc(fam(c.driverFamilyId).parentName) : t('deviation.nog_geen_chauffeur');
  const cap = c.driverFamilyId? seats(fam(c.driverFamilyId)) : null;
  const over = cap!=null && girlIds.length>cap;
  const mine = !!opts.highlightId && (c.driverFamilyId===opts.highlightId || girlIds.includes(opts.highlightId));
  const overHtml = over? ` <span class="fitbad" style="white-space:nowrap" title="${t('deviation.meer_passagiers_dan_plekken')}">${phIcon('warning')} ${girlIds.length}/${cap}</span>` : '';
  const delHtml = opts.editable? `<button type="button" class="iconbtn danger" data-delmatchcar="${opts.slug}|${opts.idx}" aria-label="Verwijder carpool van ${driver}" title="${t('deviation.verwijder_carpool')}">${phIcon('trash')}</button>` : '';
  return `<div class="matchCarRow${mine?' mine':''}">
    <span class="matchCarDep">${esc(c.departureTime||'--:--')}</span>
    <span style="flex:1;min-width:0">${phIcon('car')} <strong>${driver}</strong> · ${girlIds.map(id=>girlName(id)).join(', ')||t('deviation.geen_passagiers')}${overHtml}</span>
    ${delHtml}
  </div>`;
}

export function renderWeekendMatchCarpoolCard(){
  const weekendMatches = matchesNext8Days(currentMatchList());
  S.weekendMatchBySlug = {};
  if(!weekendMatches.length){
    return `<div class="card" id="matchCarpoolCard"><h2>${t('deviation.wedstrijdcarpool_komende_dagen')}</h2><p class="muted">${t('deviation.geen_wedstrijden_gevonden')}</p></div>`;
  }
  const allFamilies = Object.entries(S.families);
  const matchesHtml = weekendMatches.map(m=>{
    const slug = matchSlug(m);
    S.weekendMatchBySlug[slug] = m;
    const cp = carpoolFor(m);
    const cars = (cp.doc && cp.doc.cars) || [];
    const carsHtml = cars.length? cars.map((c,idx)=>matchCarRowHtml(c,{editable:true, slug:cp.id, idx})).join('') : t('deviation.p_class_muted_style_font');
    const isOpen = S.openMatchCarpoolForm===slug;
    let formHtml;
    if(isOpen){
      const suggestedDep = suggestedMatchDeparture(m.start);
      const girlOptions = allFamilies.map(([id,f])=>`<label class="chip"><input type="checkbox" class="matchCarGirlPick" value="${id}">${esc(f.girlName||f.parentName||id)}</label>`).join('');
      const driverOptions = allFamilies.map(([id,f])=>`<option value="${id}">${esc(f.parentName)} (${seats(f)} ${seats(f)===1?t('common.plek'):t('common.plekken')})</option>`).join('');
      formHtml = `<div class="dayFormCard" style="margin-top:8px">
        <label style="margin-top:0">${t('deviation.chauffeur')}</label>
        <select id="matchCarDriver_${slug}"><option value="">${t('deviation.kies')}</option>${driverOptions}</select>
        <label>${t('deviation.welke_passagiers')} <span id="matchCarCount_${slug}"></span></label>
        <div>${girlOptions}</div>
        <div id="matchCarCapWarn_${slug}" class="matchCapWarn" role="status" aria-live="polite"></div>
        <label>${t('deviation.vertrektijd')}</label>
        <input type="time" id="matchCarTime_${slug}" value="${suggestedDep}">
        <button type="button" class="btn small secondary" data-savematchcar="${slug}">${t('deviation.opslaan')}</button>
        <button type="button" class="btn small secondary" data-cancelmatchcar="${slug}">${t('common.annuleren')}</button>
      </div>`;
    } else {
      formHtml = `<button type="button" class="btn small secondary" data-addmatchcar="${slug}" style="margin-top:6px">${t('deviation.auto_toevoegen')}</button>`;
    }
    return `<div class="group matchGroup">${matchInfoHtml(m)}${carsHtml}${formHtml}</div>`;
  }).join('');
  return `<div class="card" id="matchCarpoolCard">
    <h2>${t('deviation.wedstrijdcarpool_komende_dagen')}</h2>
    <p class="muted">${t('deviation.zet_een_carpool_op_voor')}</p>
    ${matchesHtml}
  </div>`;
}

export function updateMatchCarCapacityWarning(slug){
  const st = matchCarCapacityState(slug);
  const cnt=document.getElementById('matchCarCount_'+slug);
  if(cnt) cnt.textContent = st.n? '('+t('deviation.gekozen',{n:st.n})+(st.cap!=null?` / ${st.cap} ${st.cap===1?t('common.plek'):t('common.plekken')}`:'')+')' : '';
  const warn=document.getElementById('matchCarCapWarn_'+slug);
  if(warn) warn.innerHTML = st.over
    ? t('deviation.heeft_maar_je_hebt_passagiers', { p1: phIcon('warning'), p2: esc(fam(st.driverId).parentName), p3: st.cap, p4: st.cap===1?'passagiersplek':'passagiersplekken', p5: st.n })
    : '';
  // Any change to the selection cancels a pending "toch opslaan" confirmation.
  const saveBtn=document.querySelector(`[data-savematchcar="${slug}"]`);
  if(saveBtn && saveBtn.dataset.confirmOver==='1'){ saveBtn.dataset.confirmOver=''; saveBtn.textContent=t('deviation.opslaan'); }
}

export function wireWeekendMatchCarpool(){
  if(S.openMatchCarpoolForm){
    const slug=S.openMatchCarpoolForm;
    const driverSel=document.getElementById('matchCarDriver_'+slug);
    if(driverSel) driverSel.onchange=()=>updateMatchCarCapacityWarning(slug);
    document.querySelectorAll('.matchCarGirlPick').forEach(c=>c.onchange=()=>updateMatchCarCapacityWarning(slug));
  }
  document.querySelectorAll('[data-addmatchcar]').forEach(b=>b.onclick=()=>{ S.openMatchCarpoolForm=b.dataset.addmatchcar; hapticTap(); renderDeviationTab(); });
  document.querySelectorAll('[data-cancelmatchcar]').forEach(b=>b.onclick=()=>{ S.openMatchCarpoolForm=null; renderDeviationTab(); });
  document.querySelectorAll('[data-savematchcar]').forEach(b=>b.onclick=async ()=>{
    const slug=b.dataset.savematchcar;
    const driverSel=document.getElementById('matchCarDriver_'+slug);
    const timeInp=document.getElementById('matchCarTime_'+slug);
    const girlIds=[...document.querySelectorAll('.matchCarGirlPick:checked')].map(c=>c.value);
    if(!driverSel || !driverSel.value){ showToast(t('deviation.kies_een_chauffeur')); return; }
    if(!girlIds.length){ showToast(t('deviation.kies_minstens_1_dochter')); return; }
    const capState = matchCarCapacityState(slug);
    if(capState.over && b.dataset.confirmOver!=='1'){
      b.dataset.confirmOver='1'; b.textContent=t('deviation.toch_opslaan');
      showToast(t('deviation.te_veel_passagiers_tik_nogmaals', { p1: capState.n, p2: capState.cap }), {icon:'warning'});
      return;
    }
    const m = S.weekendMatchBySlug[slug];
    if(!m){ showToast(t('deviation.kon_deze_wedstrijd_niet_vinden')); return; }
    const cp = carpoolFor(m);
    const newCar = {driverFamilyId:driverSel.value, girlIds, departureTime:timeInp.value};
    const cars = cp.doc? [...(cp.doc.cars||[]), newCar] : [newCar];
    try{
      await db.doc("matchCarpools/"+slug).set({matchSlug:slug, calendarId:m.calendarId||'', eventId:m.eventId||'', teamLabel:matchLabel(m), summary:m.summary, location:m.location||'', startMs:m.start.getTime(), cars});
      // An old name-keyed document is moved over to the ID-keyed one.
      if(cp.doc && cp.id!==slug){ try{ await db.doc("matchCarpools/"+cp.id).delete(); }catch(e){} }
      S.openMatchCarpoolForm=null;
      showToast(t('deviation.carpool_toegevoegd'));
    }catch(e){ showToast(t('data.opslaan_mislukt')+(e&&e.message||e)); }
  });
  document.querySelectorAll('[data-delmatchcar]').forEach(b=>b.onclick=async ()=>{
    const [slug,idxStr]=b.dataset.delmatchcar.split('|'); const idx=+idxStr;
    const existing=S.matchCarpools[slug]; if(!existing) return;
    const cars = existing.cars.filter((_,i)=>i!==idx);
    try{
      if(cars.length) await db.doc("matchCarpools/"+slug).set({...existing, cars});
      else await db.doc("matchCarpools/"+slug).delete();
    }catch(e){ showToast(t('beheer.verwijderen_mislukt')+(e&&e.message||e)); }
  });
}

export function sendWhatsAppUpdate(buildFn){
  const msg = (typeof buildFn==='function'? buildFn : buildWhatsAppMessage)();
  window.open('https://wa.me/?text='+encodeURIComponent(msg), '_blank', 'noopener,noreferrer');
}

export function whatsAppButtonHtml(btnId){
  btnId = btnId || 'waUpdateBtn';
  return `<button type="button" class="btn secondary" id="${btnId}" style="display:inline-flex;align-items:center">${WHATSAPP_SVG}${t('deviation.deel_update_via_whatsapp')}</button>`;
}

export function wireWhatsAppButton(btnId, buildFn){
  const btn=document.getElementById(btnId || 'waUpdateBtn');
  if(btn) btn.onclick=()=>sendWhatsAppUpdate(buildFn);
}

export function renderDeviationTab(){
  const box=document.getElementById('tab-deviation');
  if(!box) return;
  if(!S.me){ box.innerHTML=`<div class="card"><h2>${t('deviation.wijzigen')}</h2><p class="muted">${t('deviation.kon_je_account_niet_herkennen')}</p></div>`; return; }
  // Same as Rooster: a day is always open (today, or Monday on a weekend) and a tap on a pill loads that day.
  if(!S.deviationDay || !DAYS.some(([k])=>k===S.deviationDay)) S.deviationDay = todayKey || 'Ma';
  const day = S.deviationDay;
  const dayLabel = DAYS.find(([k])=>k===day)[1];
  const changedDays = DAYS.filter(([k])=>activeDeviation(k,'heen')||activeDeviation(k,'terug')).map(([k])=>k);
  const pillsHtml = DAYS.map(([k,label])=>{
    const changed = changedDays.includes(k);
    const isActive = k===day;
    return `<button type="button" class="daypill devDayPill${isActive?' active':''}${changed?' changed':''}" data-devday="${k}" aria-pressed="${isActive}" aria-label="${label} ${dateForWeekday(k).getDate()}${changed?t('deviation.gewijzigd'):''}">
      <span class="daypillTop">${dayUp(k)}</span>
      <span class="daypillSub">${dateForWeekday(k).getDate()}</span>
      ${k===todayKey? t('schedule.span_class_daypilltoday_aria_hidden') : ''}
      ${changed? '<span class="devDayDot" aria-hidden="true"></span>' : ''}
    </button>`;
  }).join('');
  box.innerHTML = `<div class="devAlert">
      <p class="devAlertTitle">${phIcon('lightning')} ${t('deviation.wijzigingen')} ${weekRangeLabel()}</p>
      <p class="devAlertBody">${t('deviation.eenmalige_ritaanpassing_voor_deze_week')}</p>
    </div>
    <div class="daypills" role="group" aria-label="${t('deviation.kies_een_dag')}">${pillsHtml}</div>
    ${changedDays.length? `<p class="muted" style="margin:-6px 2px 10px;display:flex;align-items:center;gap:6px"><span class="devDayDot" style="position:static" aria-hidden="true"></span> ${t('deviation.deze_week_gewijzigd')}</p>` : ''}
    <div class="daysection"><h3>${dayLabel}</h3>
      <p class="muted" style="margin:0 0 8px">${t('deviation.wijzigingen_hier_gelden_alleen_voor')} ${dayLabel.toLowerCase()} ${t('deviation.deze_week_en_verdwijnen_dit')}</p>
      ${renderDevDirection(day,'heen')}
      ${renderDevDirection(day,'terug')}
      ${conclusieCardHtml(day)}
    </div>
    ${renderWeekendMatchCarpoolCard()}
    ${lastUpdateFooter(S.lastUpdateDeviation)}`;
  document.querySelectorAll('[data-devday]').forEach(b=>b.onclick=()=>{ S.deviationDay=b.dataset.devday; hapticTap(); renderDeviationTab(); });
  wireWhatsAppButton('conclusieBtn', ()=>buildConclusieMessage(day));
  wireWeekendMatchCarpool();
  attachDeviationHandlers();
}

// US-03: the auto-drafted "conclusie-appje" for the open day. Highlighted for that day's coordinator (US-02);
// every other parent can use it too. The button only opens WhatsApp with the text filled in: nothing is sent.
export function conclusieCardHtml(day){
  const dayLabel = DAYS.find(([k])=>k===day)[1];
  const dc = dayCoordinatorFor(S, day);
  const me = myLinkedFamilyId();
  const forYou = !!(dc && me && dc.familyId===me);
  return `<div class="card conclusieCard${forYou?' forYou':''}" id="conclusieCard">
    <h2 style="margin-top:0">${t('conclusie.title', { dayLabel })}</h2>
    <p class="muted" style="margin:0">${forYou? t('conclusie.forYou', { day: dayLabel.toLowerCase() }) : t('conclusie.intro')}</p>
    <div class="conclusiePreview" aria-label="${t('conclusie.previewLabel')}">${esc(buildConclusieMessage(day))}</div>
    <button type="button" class="btn${forYou?'':' secondary'}" id="conclusieBtn" style="display:inline-flex;align-items:center">${WHATSAPP_SVG}${t('conclusie.button')}</button>
  </div>`;
}

// US-05: Flex families sign up per day and direction, as passenger or as driver.
// A parent sees their own family (when it is Flex); the coordinator sees every Flex family.
export function flexSignupHtml(day,direction,cars){
  const mine = myLinkedFamilyId();
  const flexFams = Object.entries(S.families).filter(([id,f])=>isFlex(f) && (S.canEdit || id===mine));
  if(!flexFams.length) return '';
  const freeIdx = carsWithFreeSeat(cars, id=>seats(fam(id)));
  const timeLabel = direction==='heen'? t('flex.timeHeen') : t('flex.timeTerug');
  const rows = flexFams.map(([id,f])=>{
    const key = `${day}|${direction}|${id}`;
    const head = `<strong>${esc(f.girlName||f.parentName||id)}</strong> <span class="badge flexBadge">${t('flex.badge')}</span>`;
    if(flexIsSignedUp(cars,id)){
      return `<div class="rowflex flexRow" style="padding:6px 0;border-bottom:1px solid var(--border)"><span style="flex:1">${head} · ${t('flex.signedUp')}</span>
        <button type="button" class="btn small secondary" data-flexoff="${key}">${t('flex.signOff')}</button></div>`;
    }
    const carOptions = `<option value="">${t('flex.chooseCar')}</option>` + freeIdx.map(i=>`<option value="${i}">${t('deviation.auto')} ${driverNameHtml(cars[i].driverFamilyId)}</option>`).join('');
    const canDrive = seats(f)>=1;
    return `<div class="flexRow" style="padding:6px 0;border-bottom:1px solid var(--border)">
      <div>${head}</div>
      <label style="margin-top:6px" for="flexTime_${key}">${timeLabel}</label>
      <input type="time" id="flexTime_${key}" class="flexTimeInp">
      <div class="rowflex" style="gap:6px;margin-top:6px;flex-wrap:wrap">
        ${freeIdx.length? `<select id="flexCar_${key}" class="flexCarSel" style="width:auto">${carOptions}</select>
        <button type="button" class="btn small" data-flexpass="${key}">${t('flex.rideAlong')}</button>` : `<span class="muted">${t('flex.noFreeSeat')}</span>`}
        ${canDrive? `<button type="button" class="btn small secondary" data-flexdrive="${key}">${phIcon('car')} ${t('flex.drive')}</button>` : `<span class="muted">${t('flex.noCarToDrive')}</span>`}
      </div>
    </div>`;
  }).join('');
  return `<div class="group flexSignup" style="border-style:dashed">
    <h3 style="margin-bottom:4px">${t('flex.title')}</h3>
    <p class="muted" style="margin:0 0 4px">${t('flex.intro')}</p>
    ${rows}
  </div>`;
}

// US-04: WhatsApp buttons to talk 1-op-1 with the driver of each car. The day coordinator shares the decision.
export function oneOnOneHtml(day,direction,cars){
  const me = myLinkedFamilyId();
  const buttons = cars.map(c=>{
    if(!c.driverFamilyId || c.driverFamilyId===me) return '';
    const f = fam(c.driverFamilyId);
    const num = waPhone(f.parentPhone1);
    if(!num) return '';
    const text = t('wa.oneOnOne', { direction: direction==='heen'? t('wa.dir.heen') : t('wa.dir.terug'), date: waDayDate(day) });
    const href = 'https://wa.me/'+num+'?text='+encodeURIComponent(text);
    const name = f.parentName||'?';
    return `<a class="btn small secondary oneOnOneBtn" href="${esc(href)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(t('oneOnOne.aria', { name }))}" style="display:inline-flex;align-items:center;gap:6px;text-decoration:none">${WA_ICON_SMALL.replace('<svg ','<svg width="16" height="16" ')}${esc(t('oneOnOne.button', { name }))}</a>`;
  }).filter(Boolean);
  if(!buttons.length) return '';
  return `<div class="oneOnOne"><div class="rowflex" style="gap:6px;flex-wrap:wrap">${buttons.join('')}</div><p class="oneOnOneHint">${t('oneOnOne.label')}</p></div>`;
}

export function renderDevDirection(day,direction){
  const cars = effectiveCars(day,direction);
  const dev = activeDeviation(day,direction);
  const allFamilies = Object.entries(S.families);
  const assignedIds = new Set(cars.flatMap(c=>c.girlIds));
  const unassigned = allFamilies.filter(([id])=>!assignedIds.has(id));

  const myIdDev = myFamilyId();
  const locCfg = locationsCfg();
  const cardsHtml = cars.map((c,idx)=>{
    // One-off pickup/drop-off place (US-15): empty = the default of this direction.
    const chosen = locCfg.places.some(p=>p.id===c.locationId)? c.locationId : '';
    const locationOptions = `<option value="" ${chosen===''?'selected':''}>${esc(t('loc.useDefault',{name:placeFor({}, direction, locCfg).name}))}</option>` +
      locCfg.places.map(p=>`<option value="${p.id}" ${p.id===chosen?'selected':''}>${esc(p.name)}</option>`).join('');
    const driverOk = c.driverFamilyId? (isFlex(fam(c.driverFamilyId)) || isAvailable(fam(c.driverFamilyId),day,direction)) : true;
    const driverOptions = `<option value="" ${!c.driverFamilyId?'selected':''}>${t('deviation.geen_chauffeur')}</option>` +
      allFamilies.map(([id,f])=>`<option value="${id}" ${id===c.driverFamilyId?'selected':''}>${esc(f.parentName)}${isFlex(f)? ' ('+t('flex.speelsterChauffeur')+')' : (isAvailable(f,day,direction)?'':t('deviation.geen_beschikbaarheid'))}</option>`).join('');
    const otherIdxs = cars.map((_,i)=>i).filter(i=>i!==idx);
    const swapOptions = `<option value="">${t('deviation.verplaats_naar')}</option>` + otherIdxs.map(i=>`<option value="${i}">${t('deviation.auto')} ${esc(fam(cars[i].driverFamilyId).parentName||'?')}</option>`).join('');
    const passengerRows = c.girlIds.map(id=>`
      <div class="rowflex" style="padding:4px 0;border-bottom:1px solid var(--border)">
        <span style="flex:1${id===myIdDev?';font-weight:800;color:var(--danger)':''}">${girlName(id)}</span>
        ${otherIdxs.length? `<select class="devSwapSel" data-day="${day}" data-direction="${direction}" data-caridx="${idx}" data-girl="${id}" style="width:auto;font-size:12px" aria-label="${girlName(id)} verplaatsen naar andere auto">${swapOptions}</select>` : ''}
        <button type="button" class="iconbtn danger devRemoveBtn" data-day="${day}" data-direction="${direction}" data-caridx="${idx}" data-girl="${id}" aria-label="Verwijder ${girlName(id)} uit auto" title="${t('deviation.verwijder_uit_auto')}">${phIcon('trash')}</button>
      </div>`).join('') || t('deviation.p_class_muted_geen_passagiers');
    return `<div class="group devCard" data-devcar="${day}|${direction}|${idx}">
      <div class="dir">${t('deviation.vertrek')}</div>
      <input type="time" class="devDeptimeInp timeBig" data-day="${day}" data-direction="${direction}" data-caridx="${idx}" value="${c.departureTime||''}" aria-label="${t('deviation.vertrektijd')}">
      <label style="margin-top:8px">${t('deviation.chauffeur')}</label>
      <select class="devDriverSel" data-day="${day}" data-direction="${direction}" data-caridx="${idx}">${driverOptions}</select>
      <label style="margin-top:8px" for="devLoc_${day}_${direction}_${idx}">${t('loc.override')}</label>
      <select class="devLocSel" id="devLoc_${day}_${direction}_${idx}" data-day="${day}" data-direction="${direction}" data-caridx="${idx}">${locationOptions}</select>
      ${!driverOk? `<p class="fitbad" style="font-size:11px;margin-top:2px">${phIcon('warning')} ${t('deviation.deze_ouder_heeft_voor_dit')}</p>` : ''}
      <div style="margin-top:8px">${passengerRows}</div>
    </div>`;
  }).join('') || `<p class="muted">${t('deviation.geen_ritten_gepland_in_het')}</p>`;

  const addOptions = cars.length? `<option value="">${t('deviation.voeg_toe_aan_auto')}</option>` + cars.map((c,i)=>`<option value="${i}">${t('deviation.auto')} ${esc(fam(c.driverFamilyId).parentName||'?')}</option>`).join('') : '';
  const unassignedHtml = unassigned.length? `<div class="group" style="border-style:dashed">
      <h3 style="margin-bottom:6px">${t('deviation.andere_meiden')}</h3>
      <p class="muted" style="margin-top:0">${t('deviation.ook_meiden_die_niet_standaard')}</p>
      ${unassigned.map(([id,f])=>`
        <div class="rowflex" style="padding:4px 0;border-bottom:1px solid var(--border)">
          <span style="flex:1">${esc(f.girlName||f.parentName||id)}</span>
          ${cars.length? `<select class="devAddSel" data-day="${day}" data-direction="${direction}" data-girl="${id}" style="width:auto;font-size:12px">${addOptions}</select>` : t('deviation.span_class_muted_nog_geen')}
        </div>`).join('')}
    </div>` : '';

  return `<div class="card">
    ${dirLabelHtml(direction)}
    ${cardsHtml}
    ${oneOnOneHtml(day,direction,cars)}${flexSignupHtml(day,direction,cars)}
    ${unassignedHtml}
    ${dev? `<button type="button" class="btn small secondary" data-devreset="${day}|${direction}">${t('deviation.terug_naar_standaard_rooster')}</button>` : ''}
  </div>`;
}

export function attachDeviationHandlers(){
 try{
  document.querySelectorAll('.devDriverSel').forEach(sel=>sel.onchange=async ()=>{
    const {day,direction,caridx}=sel.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    cars[idx]={...cars[idx], driverFamilyId: sel.value||null};
    await saveDeviationCars(day,direction,cars);
  });
  document.querySelectorAll('.devLocSel').forEach(sel=>sel.onchange=async ()=>{
    const {day,direction,caridx}=sel.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    cars[idx]={...cars[idx], locationId: sel.value||undefined};   // undefined = back to the default; saveDeviationCars leaves it out
    await saveDeviationCars(day,direction,cars);
  });
  document.querySelectorAll('.devDeptimeInp').forEach(inp=>inp.onchange=async ()=>{
    const {day,direction,caridx}=inp.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    cars[idx]={...cars[idx], departureTime: inp.value};
    await saveDeviationCars(day,direction,cars);
  });
  document.querySelectorAll('.devRemoveBtn').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,caridx,girl}=btn.dataset; const idx=+caridx;
    const cars=effectiveCars(day,direction);
    const newGirlIds=cars[idx].girlIds.filter(id=>id!==girl);
    cars[idx]={...cars[idx], girlIds:newGirlIds, departureTime: computeDepartureTime(day,direction,newGirlIds)};
    const ok = await saveDeviationCars(day,direction,cars);
    if(ok) showToast(girlName(girl)+t('deviation.verwijderd_uit_deze_auto'));
  });
  document.querySelectorAll('.devSwapSel').forEach(sel=>sel.onchange=async ()=>{
    if(!sel.value) return;
    const {day,direction,caridx,girl}=sel.dataset; const fromIdx=+caridx; const toIdx=+sel.value;
    const cars=effectiveCars(day,direction);
    const newFrom=cars[fromIdx].girlIds.filter(id=>id!==girl);
    const newTo=[...cars[toIdx].girlIds, girl];
    const toSeatsAvail = cars[toIdx].driverFamilyId? seats(fam(cars[toIdx].driverFamilyId)) : null;
    const overfull = toSeatsAvail!=null && newTo.length>toSeatsAvail;
    cars[fromIdx]={...cars[fromIdx], girlIds:newFrom, departureTime: computeDepartureTime(day,direction,newFrom)};
    cars[toIdx]={...cars[toIdx], girlIds:newTo, departureTime: computeDepartureTime(day,direction,newTo)};
    const ok = await saveDeviationCars(day,direction,cars);
    if(ok){
      if(overfull) showToast(t('deviation.deze_auto_zit_nu_vol', { p1: newTo.length, p2: toSeatsAvail }), {icon:'warning'});
      else showToast(girlName(girl)+t('deviation.verplaatst'));
    }
  });
  document.querySelectorAll('.devAddSel').forEach(sel=>sel.onchange=async ()=>{
    if(!sel.value) return;
    const {day,direction,girl}=sel.dataset; const toIdx=+sel.value;
    const cars=effectiveCars(day,direction);
    const newTo=[...cars[toIdx].girlIds, girl];
    const toSeatsAvail = cars[toIdx].driverFamilyId? seats(fam(cars[toIdx].driverFamilyId)) : null;
    const overfull = toSeatsAvail!=null && newTo.length>toSeatsAvail;
    cars[toIdx]={...cars[toIdx], girlIds:newTo, departureTime: computeDepartureTime(day,direction,newTo)};
    const ok = await saveDeviationCars(day,direction,cars);
    if(ok){
      if(overfull) showToast(t('deviation.deze_auto_zit_nu_vol_2', { p1: newTo.length, p2: toSeatsAvail }), {icon:'warning'});
      else showToast(girlName(girl)+t('deviation.toegevoegd'));
    }
  });
  function flexCtx(btn, attr){
    const [day,direction,id]=btn.dataset[attr].split('|');
    const timeEl=document.getElementById(`flexTime_${day}|${direction}|${id}`);
    const carEl=document.getElementById(`flexCar_${day}|${direction}|${id}`);
    return {day,direction,id,time:timeEl&&timeEl.value, carIdx:carEl&&carEl.value};
  }
  const lead = ()=> (S.settings&&S.settings.travelLeadMinutes)||60;
  document.querySelectorAll('[data-flexpass]').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,id,time,carIdx}=flexCtx(btn,'flexpass');
    if(!time){ showToast(t('flex.chooseTime')); return; }
    if(carIdx===''||carIdx==null){ showToast(t('flex.chooseCarToast')); return; }
    const cars=flexJoinCar(effectiveCars(day,direction), +carIdx, id, time, direction, lead());
    if(await saveDeviationCars(day,direction,cars)) showToast(t('flex.joined', { p1: girlName(id) }));
  });
  document.querySelectorAll('[data-flexdrive]').forEach(btn=>btn.onclick=async ()=>{
    const {day,direction,id,time}=flexCtx(btn,'flexdrive');
    if(!time){ showToast(t('flex.chooseTime')); return; }
    const cars=flexDriveOwn(effectiveCars(day,direction), id, time, direction, lead());
    if(await saveDeviationCars(day,direction,cars)) showToast(t('flex.driving', { p1: girlName(id) }));
  });
  document.querySelectorAll('[data-flexoff]').forEach(btn=>btn.onclick=async ()=>{
    const [day,direction,id]=btn.dataset.flexoff.split('|');
    const cars=flexSignOff(effectiveCars(day,direction), id);
    if(await saveDeviationCars(day,direction,cars)) showToast(t('flex.removed', { p1: girlName(id) }));
  });
  document.querySelectorAll('[data-devreset]').forEach(btn=>btn.onclick=()=>twoStepConfirm(btn,t('deviation.zeker_terug_naar_standaard_rooster'),async ()=>{
    const [day,direction]=btn.dataset.devreset.split('|');
    // Written as an empty deviation instead of a delete: activeDeviation() ignores empty `cars`,
    // and deletes of a current-week deviation are refused by firestore.rules until it expires.
    try{ refreshWeekKey(); await db.doc("deviations/"+deviationKey(day,direction)).set({day,direction,weekKey:S.currentWeekKey,expiresAt:deviationExpiryMs(),cars:[]}); S.lastDeviationEditDay = day; recordLastUpdate('Deviation'); showToast(t('deviation.teruggezet_naar_standaard')); }
    catch(e){ showToast(t('data.mislukt')+(e&&e.message||e)); }
  }));
 }catch(e){ showToast(t('beheer.fout_bij_koppelen_knoppen')+(e&&e.message||e)); }
}
